arguments.command:
cat << 'HTMLEOF' > /app/output/poster.html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>JS Framework Benchmark: 5 Years of Browser Performance Testing</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&family=JetBrains+Mono:wght@400;600;700&display=swap');

* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-deep: #0B1120;
  --bg-card: #0f172a;
  --bg-elevated: #151e32;
  --border: #1e293b;
  --text-primary: #f1f5f9;
  --text-secondary: #94a3b8;
  --accent-blue: #38bdf8;
  --accent-teal: #2dd4bf;
  --accent-amber: #f59e0b;
  --accent-rose: #fb7185;
  --grid: #1e293b;
}

body {
  background: var(--bg-deep);
  color: var(--text-primary);
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  width: 2400px;
  min-height: 3394px;
  overflow-x: hidden;
}

.poster {
  width: 2400px;
  min-height: 3394px;
  padding: 80px 100px;
  background:
    radial-gradient(ellipse at 20% 0%, rgba(56,189,248,0.08) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 100%, rgba(45,212,191,0.06) 0%, transparent 50%),
    var(--bg-deep);
  position: relative;
}

/* Subtle grid pattern */
.poster::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image:
    linear-gradient(var(--grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid) 1px, transparent 1px);
  background-size: 40px 40px;
  opacity: 0.4;
  pointer-events: none;
}

.section { position: relative; z-index: 1; margin-bottom: 60px; }

/* Header */
.header { text-align: center; margin-bottom: 70px; padding-top: 20px; }
.header-badge {
  display: inline-block;
  background: rgba(56,189,248,0.12);
  border: 1px solid rgba(56,189,248,0.25);
  color: var(--accent-blue);
  font-family: 'JetBrains Mono', monospace;
  font-size: 18px;
  font-weight: 600;
  padding: 8px 24px;
  border-radius: 100px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 30px;
}
.header h1 {
  font-size: 80px;
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-blue) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 24px;
}
.header p {
  font-size: 28px;
  color: var(--text-secondary);
  max-width: 1400px;
  margin: 0 auto;
  line-height: 1.5;
}

/* Hero Stats */
.hero-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-bottom: 80px;
}
.stat-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 48px 36px;
  text-align: center;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s;
}
.stat-card::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-teal));
}
.stat-card.warning::after {
  background: linear-gradient(90deg, var(--accent-amber), var(--accent-rose));
}
.stat-card.accent::after {
  background: linear-gradient(90deg, var(--accent-teal), var(--accent-blue));
}
.stat-number {
  font-family: 'JetBrains Mono', monospace;
  font-size: 72px;
  font-weight: 700;
  color: var(--accent-blue);
  line-height: 1;
  margin-bottom: 16px;
}
.stat-card.warning .stat-number { color: var(--accent-amber); }
.stat-card.accent .stat-number { color: var(--accent-teal); }
.stat-label {
  font-size: 20px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 10px;
}
.stat-context {
  font-size: 16px;
  color: var(--text-secondary);
  line-height: 1.4;
}

/* Section titles */
.section-title {
  font-size: 42px;
  font-weight: 800;
  margin-bottom: 36px;
  display: flex;
  align-items: center;
  gap: 20px;
}
.section-title::before {
  content: '';
  width: 6px;
  height: 42px;
  background: linear-gradient(180deg, var(--accent-blue), var(--accent-teal));
  border-radius: 3px;
}
.section-subtitle {
  font-size: 22px;
  color: var(--text-secondary);
  margin-bottom: 40px;
  line-height: 1.5;
}

/* Timeline */
.timeline-container {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 50px 40px;
  position: relative;
}
.timeline-track {
  position: relative;
  height: 200px;
  margin: 40px 0;
}
.timeline-line {
  position: absolute;
  top: 50%;
  left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-teal), var(--accent-amber));
  border-radius: 2px;
  transform: translateY(-50%);
}
.timeline-year {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  z-index: 2;
}
.timeline-year-dot {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-deep);
  border: 4px solid var(--accent-blue);
  margin: 0 auto 12px;
  box-shadow: 0 0 20px rgba(56,189,248,0.3);
}
.timeline-year.warning .timeline-year-dot { border-color: var(--accent-amber); box-shadow: 0 0 20px rgba(245,158,11,0.3); }
.timeline-year.teal .timeline-year-dot { border-color: var(--accent-teal); box-shadow: 0 0 20px rgba(45,212,191,0.3); }
.timeline-year-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 24px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 6px;
}
.timeline-year-range {
  font-family: 'JetBrains Mono', monospace;
  font-size: 16px;
  color: var(--text-secondary);
}
.timeline-year-runs {
  font-size: 14px;
  color: var(--accent-blue);
  margin-top: 6px;
  font-weight: 600;
}
.timeline-milestone {
  position: absolute;
  top: 20px;
  transform: translateX(-50%);
  background: rgba(245,158,11,0.12);
  border: 1px solid rgba(245,158,11,0.4);
  border-radius: 12px;
  padding: 16px 20px;
  text-align: center;
  min-width: 220px;
}
.timeline-milestone::after {
  content: '';
  position: absolute;
  bottom: -10px;
  left: 50%;
  transform: translateX(-50%);
  width: 2px;
  height: 30px;
  background: var(--accent-amber);
}
.timeline-milestone-title {
  font-family: 'JetBrains Mono', monospace;
  font-size: 18px;
  font-weight: 700;
  color: var(--accent-amber);
  margin-bottom: 4px;
}
.timeline-milestone-desc {
  font-size: 14px;
  color: var(--text-secondary);
}
.chrome-versions-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 30px;
  padding: 24px 30px;
  background: var(--bg-elevated);
  border-radius: 16px;
  border: 1px solid var(--border);
}
.chrome-start, .chrome-end {
  text-align: center;
}
.chrome-start .chrome-num, .chrome-end .chrome-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 48px;
  font-weight: 700;
}
.chrome-start .chrome-num { color: var(--accent-blue); }
.chrome-end .chrome-num { color: var(--accent-teal); }
.chrome-start .chrome-label, .chrome-end .chrome-label {
  font-size: 16px;
  color: var(--text-secondary);
  margin-top: 4px;
}
.chrome-arrow {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 0 40px;
}
.chrome-arrow-line {
  flex: 1;
  height: 3px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-teal));
  border-radius: 2px;
  position: relative;
}
.chrome-arrow-line::after {
  content: '';
  position: absolute;
  right: -2px;
  top: 50%;
  transform: translateY(-50%);
  border: 8px solid transparent;
  border-left: 12px solid var(--accent-teal);
}
.chrome-arrow-text {
  font-family: 'JetBrains Mono', monospace;
  font-size: 20px;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
}

/* Methodology */
.methodology-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
}
.method-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 40px;
}
.method-card.before { border-top: 4px solid var(--accent-blue); }
.method-card.after { border-top: 4px solid var(--accent-amber); }
.method-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}
.method-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 16px;
  font-weight: 700;
  padding: 8px 16px;
  border-radius: 8px;
  background: rgba(56,189,248,0.12);
  color: var(--accent-blue);
}
.method-card.after .method-badge {
  background: rgba(245,158,11,0.12);
  color: var(--accent-amber);
}
.method-title {
  font-size: 28px;
  font-weight: 700;
}
.method-list {
  list-style: none;
}
.method-list li {
  font-size: 20px;
  color: var(--text-secondary);
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.method-list li:last-child { border-bottom: none; }
.method-list li::before {
  content: '›';
  color: var(--accent-teal);
  font-size: 24px;
  font-weight: 700;
  line-height: 1;
}
.method-card.after .method-list li::before { color: var(--accent-amber); }
.method-highlight {
  margin-top: 30px;
  padding: 24px;
  background: rgba(245,158,11,0.08);
  border: 1px solid rgba(245,158,11,0.2);
  border-radius: 14px;
  display: flex;
  align-items: center;
  gap: 20px;
}
.method-highlight-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: rgba(245,158,11,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
}
.method-highlight-text {
  font-size: 20px;
  color: var(--text-secondary);
  line-height: 1.5;
}
.method-highlight-text strong {
  color: var(--accent-amber);
  font-weight: 700;
}

/* Coverage */
.coverage-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
}
.coverage-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 40px;
}
.coverage-chart {
  margin: 30px 0;
}
.coverage-bar {
  display: flex;
  height: 48px;
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 20px;
}
.coverage-bar-osx {
  width: 95%;
  background: linear-gradient(90deg, var(--accent-teal), var(--accent-blue));
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'JetBrains Mono', monospace;
  font-size: 18px;
  font-weight: 700;
}
.coverage-bar-win {
  width: 5%;
  background: var(--accent-rose);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'JetBrains Mono', monospace;
  font-size: 14px;
  font-weight: 700;
}
.coverage-legend {
  display: flex;
  justify-content: center;
  gap: 40px;
}
.coverage-legend-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 18px;
  color: var(--text-secondary);
}
.coverage-legend-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
}
.coverage-note {
  margin-top: 24px;
  padding: 20px;
  background: var(--bg-elevated);
  border-radius: 12px;
  font-size: 18px;
  color: var(--text-secondary);
  line-height: 1.6;
}
.coverage-note strong { color: var(--text-primary); }

/* Yearly runs table */
.runs-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;
}
.runs-table th {
  text-align: left;
  font-size: 16px;
  font-weight: 600;
  color: var(--text-secondary);
  padding: 16px 20px;
  border-bottom: 2px solid var(--border);
  font-family: 'JetBrains Mono', monospace;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.runs-table td {
  font-size: 18px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--border);
  color: var(--text-primary);
}
.runs-table td:nth-child(3) {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 600;
  color: var(--accent-blue);
}
.runs-table tr:hover td {
  background: rgba(56,189,248,0.04);
}

/* Takeaways */
.takeaways-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}
.takeaway-item {
  display: flex;
  align-items: flex-start;
  gap: 24px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 32px 36px;
  position: relative;
  overflow: hidden;
}
.takeaway-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 5px;
  background: linear-gradient(180deg, var(--accent-blue), var(--accent-teal));
}
.takeaway-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 36px;
  font-weight: 700;
  color: var(--accent-blue);
  line-height: 1;
  min-width: 60px;
  text-align: center;
  padding-top: 4px;
}
.takeaway-content h3 {
  font-size: 24px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--text-primary);
}
.takeaway-content p {
  font-size: 18px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* Footer */
.footer {
  margin-top: 60px;
  padding-top: 40px;
  border-top: 1px solid var(--border);
  text-align: center;
  color: var(--text-secondary);
  font-size: 16px;
  font-family: 'JetBrains Mono', monospace;
}
.footer strong { color: var(--text-primary); }

/* Infographic containers */
.infographic-wrap {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 30px;
}
</style>
</head>
<body>
<div class="poster">

  <!-- Header -->
  <div class="header">
    <div class="header-badge">Developer Report</div>
    <h1>JS Framework Benchmark</h1>
    <p>5 Years of Browser Performance Testing — A comprehensive overview of the official JavaScript web framework benchmark spanning Chrome 55 through Chrome 146, tracking how the testing methodology and ecosystem have evolved.</p>
  </div>

  <!-- Hero Stats -->
  <div class="hero-stats">
    <div class="stat-card">
      <div class="stat-number">60+</div>
      <div class="stat-label">Total Official Benchmark Runs</div>
      <div class="stat-context">From Chrome 55 (2017)<br>to Chrome 146 (2026)</div>
    </div>
    <div class="stat-card accent">
      <div class="stat-number">55 → 146</div>
      <div class="stat-label">Chrome Versions Covered</div>
      <div class="stat-context">Spanning approximately<br>8 years of browser releases</div>
    </div>
    <div class="stat-card warning">
      <div class="stat-number">Chrome 118</div>
      <div class="stat-label">Scoring Method Change</div>
      <div class="stat-context">Switched to weighted<br>geometric mean</div>
    </div>
    <div class="stat-card">
      <div class="stat-number">12</div>
      <div class="stat-label">Runs in 2025 Alone</div>
      <div class="stat-context">Chrome 132 through 143<br>Most active single year</div>
    </div>
  </div>

  <!-- Timeline Section -->
  <div class="section">
    <div class="section-title">Benchmark Timeline</div>
    <div class="section-subtitle">The Chrome 55 → 146 journey spanning ~8 years. Each dot represents an era of official benchmark runs.</div>
    <div class="timeline-container">
      <div class="timeline-track">
        <div class="timeline-line"></div>

        <div class="timeline-year" style="left: 2%;">
          <div class="timeline-year-dot"></div>
          <div class="timeline-year-label">2017</div>
          <div class="timeline-year-range">Chrome 55</div>
          <div class="timeline-year-runs">4 runs</div>
        </div>

        <div class="timeline-year" style="left: 16%;">
          <div class="timeline-year-dot"></div>
          <div class="timeline-year-label">2020</div>
          <div class="timeline-year-range">83 – 87</div>
          <div class="timeline-year-runs">5 runs</div>
        </div>

        <div class="timeline-year" style="left: 28%;">
          <div class="timeline-year-dot"></div>
          <div class="timeline-year-label">2021</div>
          <div class="timeline-year-range">88 – 96</div>
          <div class="timeline-year-runs">9 runs</div>
        </div>

        <div class="timeline-year" style="left: 40%;">
          <div class="timeline-year-dot"></div>
          <div class="timeline-year-label">2022</div>
          <div class="timeline-year-range">97 – 108</div>
          <div class="timeline-year-runs">13 runs</div>
        </div>

        <div class="timeline-year warning" style="left: 52%;">
          <div class="timeline-year-dot"></div>
          <div class="timeline-year-label">2023</div>
          <div class="timeline-year-range">109 – 120</div>
          <div class="timeline-year-runs">12 runs</div>
        </div>
        <div class="timeline-milestone" style="left: 52%;">
          <div class="timeline-milestone-title">⚠ Chrome 118</div>
          <div class="timeline-milestone-desc">Methodology Overhaul</div>
        </div>

        <div class="timeline-year" style="left: 64%;">
          <div class="timeline-year-dot"></div>
          <div class="timeline-year-label">2024</div>
          <div class="timeline-year-range">121 – 131</div>
          <div class="timeline-year-runs">12 runs</div>
        </div>

        <div class="timeline-year teal" style="left: 78%;">
          <div class="timeline-year-dot"></div>
          <div class="timeline-year-label">2025</div>
          <div class="timeline-year-range">132 – 143</div>
          <div class="timeline-year-runs">12 runs</div>
        </div>

        <div class="timeline-year" style="left: 94%;">
          <div class="timeline-year-dot"></div>
          <div class="timeline-year-label">2026</div>
          <div class="timeline-year-range">144 – 146</div>
          <div class="timeline-year-runs">3 runs</div>
        </div>
      </div>

      <div class="chrome-versions-bar">
        <div class="chrome-start">
          <div class="chrome-num">Chrome 55</div>
          <div class="chrome-label">circa 2017</div>
        </div>
        <div class="chrome-arrow">
          <div class="chrome-arrow-line"></div>
          <div class="chrome-arrow-text">~8 Years</div>
          <div class="chrome-arrow-line"></div>
        </div>
        <div class="chrome-end">
          <div class="chrome-num">Chrome 146</div>
          <div class="chrome-label">mid-2026</div>
        </div>
      </div>
    </div>
  </div>

  <!-- Methodology Section -->
  <div class="section">
    <div class="section-title">Methodology Milestones</div>
    <div class="section-subtitle">Key changes that make cross-version comparisons unreliable. The switch at Chrome 118 is the single most important breakpoint.</div>
    <div class="methodology-grid">
      <div class="method-card before">
        <div class="method-header">
          <div class="method-badge">Before Chrome 118</div>
        </div>
        <ul class="method-list">
          <li>Arithmetic mean for overall scoring</li>
          <li>Original CPU throttling factors</li>
          <li>Baseline timing instrumentation</li>
          <li>All frameworks (keyed + non-keyed) in every run</li>
        </ul>
      </div>
      <div class="method-card after">
        <div class="method-header">
          <div class="method-badge">Chrome 118+</div>
        </div>
        <ul class="method-list">
          <li><strong>Weighted geometric mean</strong> for overall scoring</li>
          <li>Recalibrated CPU throttling for realistic loads</li>
          <li>Ongoing refinements to timing &amp; driver</li>
          <li>Odd versions often keyed-only (139+)</li>
        </ul>
      </div>
    </div>
    <div class="method-highlight" style="margin-top: 40px;">
      <div class="method-highlight-icon">⚠</div>
      <div class="method-highlight-text">
        <strong>Cross-version comparisons are dangerous.</strong> Because the benchmark and its driver are constantly developing, comparisons across Chrome versions aren't always safe. Always compare within the same Chrome version.
      </div>
    </div>
  </div>

  <!-- Coverage & Runs Section -->
  <div class="section">
    <div class="section-title">Platform &amp; Framework Coverage</div>
    <div class="section-subtitle">Breakdown of runs by year and platform, plus the alternating pattern of keyed-only vs full framework runs in recent versions.</div>
    <div class="coverage-grid">
      <div class="coverage-card">
        <h3 style="font-size: 24px; font-weight: 700; margin-bottom: 10px;">Platform Distribution</h3>
        <p style="font-size: 18px; color: var(--text-secondary); margin-bottom: 20px;">The vast majority of runs were executed on macOS.</p>
        <div class="coverage-chart">
          <div class="coverage-bar">
            <div class="coverage-bar-osx">macOS 95%</div>
            <div class="coverage-bar-win">Win 5%</div>
          </div>
        </div>
        <div class="coverage-legend">
          <div class="coverage-legend-item">
            <div class="coverage-legend-dot" style="background: var(--accent-teal);"></div>
            macOS (OSX) — 60+ runs
          </div>
          <div class="coverage-legend-item">
            <div class="coverage-legend-dot" style="background: var(--accent-rose);"></div>
            Windows — 2 runs
